import re
META_HEAD = re.compile(r"\A(?:<reponame>[^<\n]*|<filename>[^<\n]*|<gh_stars>[^<\n]*)+\n")

def m1_strip_meta_header(t: str) -> str:
    return META_HEAD.sub("", t, count=1)


